entries.source:
.PreferenceSwitch[data-state="checked"] {
  background: CanvasText;
}

.PreferenceSwitch[data-disabled] {
  opacity: 0.5;
}

[data-slot="button"][data-state="pressed"] {
  opacity: 0.85;
}

[data-slot="dialog-content"][data-state="open"] {
  opacity: 1;
}

[data-slot="popover-content"] {
  max-width: 20rem;
  border: 1px solid CanvasText;
  background: Canvas;
}

[data-slot="popover-content"][data-state="open"] {
  animation: enter 140ms ease-out;
}

@keyframes enter {
  from {
    opacity: 0;
    transform: translateY(-0.25rem);
  }
}

[data-slot="toast-viewport"] {
  --app-toast-inline-offset: 1rem;
  --app-toast-bottom-offset: 0px;

  position: fixed;
  inset-inline: var(--app-toast-inline-offset);
  bottom: calc(
    env(safe-area-inset-bottom, 0px) +
    var(--app-toast-bottom-offset) +
    1rem
  );
  z-index: 50;
}

@media (prefers-reduced-motion: reduce) {
  [data-state] {
    animation-duration: 1ms;
    transition-duration: 1ms;
  }
}

